Sıfırdan tool-calling döngüsü: şema üretimi, argüman doğrulama, güvenli hesap, hata gözlemi, adım sınırı ve izleme. Sahte politika gerçek modelin yerine geçer; protokol aynıdır.

```python
# PC'de çalıştır — gerekli: yalnız standart kütüphane (json, re, inspect, ast)
# Sıfırdan tool-calling döngüsü. Gerçek LLM yerine kural tabanlı bir "politika" var:
# amaç protokolü (şema -> araç çağrısı -> gözlem -> karar) görmek, API anahtarı gerekmez.
import json, re, inspect, ast, operator

BELGELER = [
 {"id": "mk1200", "baslik": "MK-1200", "metin": "MK-1200 kablosuz kulaklık fiyatı 1200 TL. 40 saat pil ömrü vardır."},
 {"id": "x200", "baslik": "X200", "metin": "X200 akıllı saat fiyatı 4500 TL. 7 gün pil ömrü vardır."},
 {"id": "iade", "baslik": "İade", "metin": "İade süresi 14 gündür. Ücret 5-10 iş günü içinde yansır."},
]

def belge_ara(sorgu: str, k: int = 2) -> list:
    """Belge deposunda anahtar kelime araması yapar."""
    kelimeler = set(re.findall(r"[a-zçğıöşü0-9-]+", sorgu.lower()))
    puanli = []
    for b in BELGELER:
        metin = (b["baslik"] + " " + b["metin"]).lower()
        puan = sum(metin.count(kelime) for kelime in kelimeler)
        if puan: puanli.append((puan, b))
    puanli.sort(key=lambda x: -x[0])
    return [b for _, b in puanli[:k]]

def hesapla(ifade: str) -> float:
    """Yalnızca sayı ve + - * / ( ) içeren aritmetik ifadeyi hesaplar."""
    izinli = {ast.Add: operator.add, ast.Sub: operator.sub,
              ast.Mult: operator.mul, ast.Div: operator.truediv}
    def yuru(d):
        if isinstance(d, ast.Expression): return yuru(d.body)
        if isinstance(d, ast.Constant) and isinstance(d.value, (int, float)): return d.value
        if isinstance(d, ast.BinOp) and type(d.op) in izinli:
            return izinli[type(d.op)](yuru(d.left), yuru(d.right))
        raise ValueError("desteklenmeyen ifade")
    return float(yuru(ast.parse(ifade, mode="eval")))   # eval() değil: yalnız izinli düğümler

KURLAR = {("USD", "TRY"): 41.2, ("EUR", "TRY"): 44.8}
def doviz_cevir(miktar: float, kaynak: str = "USD", hedef: str = "TRY") -> float:
    """Sabit kur tablosuyla para birimi çevirir."""
    return round(float(miktar) * KURLAR[(kaynak.upper(), hedef.upper())], 2)

ARACLAR = {"belge_ara": belge_ara, "hesapla": hesapla, "doviz_cevir": doviz_cevir}
TIPLER = {float: "number", int: "integer", str: "string"}

def sema(fn):
    s = inspect.signature(fn)
    props, gerekli = {}, []
    for ad, p in s.parameters.items():
        props[ad] = {"type": TIPLER.get(p.annotation, "string")}
        if p.default is inspect.Parameter.empty: gerekli.append(ad)
    return {"type": "object", "properties": props, "required": gerekli}

TOOL_SPEC = [{"name": ad, "description": fn.__doc__.strip(), "parameters": sema(fn)}
             for ad, fn in ARACLAR.items()]
print(json.dumps(TOOL_SPEC[0], ensure_ascii=False, indent=1))

def calistir(ad, args):
    if ad not in ARACLAR:
        return {"hata": f"bilinmeyen araç: {ad}"}
    fn = ARACLAR[ad]
    try:
        for p in inspect.signature(fn).parameters.values():
            if p.default is inspect.Parameter.empty and p.name not in args:
                return {"hata": f"eksik argüman: {p.name}"}
            if p.name in args and p.annotation in TIPLER:
                deger = args[p.name]
                gecerli = (isinstance(deger, (int, float)) and not isinstance(deger, bool)
                           if p.annotation in (int, float) else isinstance(deger, p.annotation))
                if not gecerli:
                    return {"hata": f"{p.name} {TIPLER[p.annotation]} olmalı, gelen: {type(deger).__name__}"}
        return {"sonuc": fn(**args)}
    except Exception as e:
        return {"hata": f"{type(e).__name__}: {e}"}

def sahte_llm(soru, gecmis):
    # Gerçek modelin yerine geçen kural tabanlı politika: her adımda TEK JSON kararı üretir.
    if not gecmis:
        if "dolar" in soru.lower() or "usd" in soru.lower():
            m = re.search(r"(\d+)", soru)
            return {"dusun": "Döviz çevirisi gerekiyor.", "arac": "doviz_cevir",
                    "argumanlar": {"miktar": int(m.group(1)) if m else 100}}
        if "indirim" in soru.lower():
            return {"dusun": "Önce ürün fiyatını belgeden almalıyım.", "arac": "belge_ara",
                    "argumanlar": {"sorgu": "MK-1200 fiyat", "k": 1}}
        return {"dusun": "Bilgi için belge aramalıyım.", "arac": "belge_ara", "argumanlar": {"sorgu": soru}}
    son, deger = gecmis[-1], gecmis[-1]["gozlem"].get("sonuc")
    if son["arac"] == "belge_ara" and "indirim" in soru.lower():
        fiyat = re.search(r"(\d+)\s*TL", json.dumps(deger, ensure_ascii=False))
        yuzde = re.search(r"%\s*(\d+)", soru)
        if fiyat and yuzde:
            return {"dusun": "Fiyat ve indirim oranı elimde; hesaplayabilirim.", "arac": "hesapla",
                    "argumanlar": {"ifade": f"{fiyat.group(1)} * (1 - {yuzde.group(1)}/100)"}}
    if son["arac"] == "belge_ara":
        return {"dusun": "Belgeyi buldum, cevabı yazabilirim.", "final": deger[0]["metin"]}
    if son["arac"] == "hesapla":
        return {"dusun": "Hesap tamam.", "final": f"İndirimli fiyat: {deger:.2f} TL"}
    if son["arac"] == "doviz_cevir":
        return {"dusun": "Çeviri tamam.", "final": f"{deger:.2f} TL"}
    return {"final": "Sonuca ulaşamadım."}

def ajan(soru, azami_adim=6, izle=True):
    gecmis, token = [], 0
    for adim in range(1, azami_adim + 1):
        karar = sahte_llm(soru, gecmis)
        token += len(json.dumps(karar, ensure_ascii=False)) // 4
        if izle: print(f"ADIM {adim}  düşün: {karar.get('dusun', '-')}")
        if "final" in karar:
            if izle:
                print("  final:", karar["final"])
                print(f"  toplam adım={adim-1}  ~token={token}")
            return {"cevap": karar["final"], "adim": adim - 1, "token": token, "gecmis": gecmis}
        cikti = calistir(karar["arac"], karar["argumanlar"])
        token += len(json.dumps(cikti, ensure_ascii=False)) // 4
        gecmis.append({"arac": karar["arac"], "argumanlar": karar["argumanlar"], "gozlem": cikti})
        if izle:
            print(f"  araç: {karar['arac']}({json.dumps(karar['argumanlar'], ensure_ascii=False)})")
            print("  gözlem:", json.dumps(cikti, ensure_ascii=False))
    return {"cevap": "Adım sınırı aşıldı", "adim": azami_adim, "token": token, "gecmis": gecmis}

for soru in ["MK-1200 fiyatı 1200 TL. %15 indirimle kaç TL?", "250 dolar kaç TL?", "İade süresi kaç gün?"]:
    print("\nSORU:", soru)
    print("CEVAP:", ajan(soru)["cevap"])

print("\nHatalı argüman:", calistir("doviz_cevir", {"miktar": "iki yüz"}))
print("Bilinmeyen araç:", calistir("veritabani_sil", {}))

# Beklenen çıktı (kısaltıldı):
# { "name": "belge_ara", ... "required": ["sorgu"] }
# SORU: MK-1200 fiyatı 1200 TL. %15 indirimle kaç TL?
# ADIM 1  düşün: Önce ürün fiyatını belgeden almalıyım.
#   araç: belge_ara({"sorgu": "MK-1200 fiyat", "k": 1})
#   gözlem: {"sonuc": [{"id": "mk1200", ...}]}
# ADIM 2  düşün: Fiyat ve indirim oranı elimde; hesaplayabilirim.
#   araç: hesapla({"ifade": "1200 * (1 - 15/100)"})
#   gözlem: {"sonuc": 1020.0}
# ADIM 3  düşün: Hesap tamam.
#   final: İndirimli fiyat: 1020.00 TL
#   toplam adım=2  ~token=114
# CEVAP: İndirimli fiyat: 1020.00 TL
# ...
# CEVAP: 10300.00 TL
# CEVAP: İade süresi 14 gündür. Ücret 5-10 iş günü içinde yansır.
# Hatalı argüman: {'hata': 'miktar number olmalı, gelen: str'}
# Bilinmeyen araç: {'hata': 'bilinmeyen araç: veritabani_sil'}
```

Dikkat: `hesapla` içinde `eval()` yok. `ast` ile yalnızca sayı, dört işlem ve parantez düğümlerine izin verilir; `__import__('os').system(...)` gibi girdiler reddedilir. Modelin ürettiği argüman **güvenilmeyen girdidir**, doğrulama olmadan çalıştırılmaz; araç çıktısındaki [istem enjeksiyonu](term:istem-enjeksiyonu) da aynı sınıfa girer.

`model.py` — tokenizer ve transformer. Bu dosya projenin çekirdeği; sonraki iki ders bunu import ediyor.

```python
# model.py — tokenizer + decoder-only transformer (projenin çekirdeği)
import collections, math, torch, torch.nn as nn

# ---------- byte-level BPE ----------
def bpe_egit(metin, hedef_vocab=320):
    """Korpus üzerinde BPE birleşmelerini öğren. Dönüş: {(a,b): yeni_id}."""
    ids = list(metin.encode("utf-8"))
    merges = {}
    while 256 + len(merges) < hedef_vocab:
        ciftler = collections.Counter(zip(ids, ids[1:]))
        if not ciftler:
            break
        (a, b), sayi = max(ciftler.items(), key=lambda kv: (kv[1], -kv[0][0], -kv[0][1]))
        if sayi < 2:
            break
        yeni = 256 + len(merges)
        merges[(a, b)] = yeni
        out, i = [], 0
        while i < len(ids):
            if i + 1 < len(ids) and (ids[i], ids[i + 1]) == (a, b):
                out.append(yeni); i += 2
            else:
                out.append(ids[i]); i += 1
        ids = out
    return merges

def bpe_kodla(s, merges):
    """Metni token id'lerine çevir; birleşmeleri sırayla (rank sırasıyla) uygula."""
    ids = list(s.encode("utf-8"))
    for (a, b), yeni in merges.items():
        out, i = [], 0
        while i < len(ids):
            if i + 1 < len(ids) and ids[i] == a and ids[i + 1] == b:
                out.append(yeni); i += 2
            else:
                out.append(ids[i]); i += 1
        ids = out
    return ids

def bpe_coz(ids, merges):
    """Token id'lerini metne çevir. Byte-level olduğu için UNK yoktur."""
    tablo = {i: bytes([i]) for i in range(256)}
    for (a, b), yeni in merges.items():
        tablo[yeni] = tablo[a] + tablo[b]
    return b"".join(tablo[i] for i in ids).decode("utf-8", errors="replace")

# ---------- transformer ----------
class Dikkat(nn.Module):
    def __init__(self, d, h):
        super().__init__()
        self.h, self.dk = h, d // h
        self.qkv = nn.Linear(d, 3 * d)
        self.proj = nn.Linear(d, d)

    def forward(self, x, maske):
        B, T, C = x.shape
        q, k, v = self.qkv(x).split(C, dim=2)
        q = q.view(B, T, self.h, self.dk).transpose(1, 2)
        k = k.view(B, T, self.h, self.dk).transpose(1, 2)
        v = v.view(B, T, self.h, self.dk).transpose(1, 2)
        att = (q @ k.transpose(-2, -1)) / math.sqrt(self.dk)
        att = att.masked_fill(maske[:T, :T], float("-inf")).softmax(-1)
        return self.proj((att @ v).transpose(1, 2).reshape(B, T, C))

class Blok(nn.Module):
    def __init__(self, d, h):
        super().__init__()
        self.ln1, self.attn = nn.LayerNorm(d), Dikkat(d, h)
        self.ln2 = nn.LayerNorm(d)
        self.mlp = nn.Sequential(nn.Linear(d, 4 * d), nn.GELU(), nn.Linear(4 * d, d))

    def forward(self, x, maske):
        x = x + self.attn(self.ln1(x), maske)
        return x + self.mlp(self.ln2(x))

class GPT(nn.Module):
    def __init__(self, vocab, d=96, n_kat=4, h=4, baglam=32):
        super().__init__()
        self.baglam = baglam
        self.tok = nn.Embedding(vocab, d)
        self.pos = nn.Embedding(baglam, d)
        self.blocks = nn.ModuleList([Blok(d, h) for _ in range(n_kat)])
        self.ln_f = nn.LayerNorm(d)
        self.head = nn.Linear(d, vocab, bias=False)
        self.head.weight = self.tok.weight
        self.register_buffer("maske", torch.triu(torch.ones(baglam, baglam, dtype=torch.bool), 1))
        for m in self.modules():
            if isinstance(m, (nn.Linear, nn.Embedding)):
                nn.init.normal_(m.weight, 0.0, 0.02)
        for m in self.modules():
            if isinstance(m, nn.Linear) and m.bias is not None:
                nn.init.zeros_(m.bias)

    def forward(self, idx):
        B, T = idx.shape
        x = self.tok(idx) + self.pos(torch.arange(T, device=idx.device))
        for b in self.blocks:
            x = b(x, self.maske)
        return self.head(self.ln_f(x))

def lora_birlestir(model):
    """LoRALinear katmanlarını taban ağırlığa birleştir: W <- W + skala * B @ A.

    Çıkarımda adapter'ı ayrı tutmanın anlamı yoktur; birleştirme sıfır ek maliyet verir.
    """
    for isim, mod in list(model.named_modules()):
        if mod.__class__.__name__ != "LoRALinear":
            continue
        with torch.no_grad():
            mod.temel.weight += mod.skala * (mod.B @ mod.A)
        ebeveyn = model.get_submodule(isim.rsplit(".", 1)[0])
        setattr(ebeveyn, isim.rsplit(".", 1)[-1], mod.temel)
    return model
```

Otomatik denetim: meta veri + CSV tutarlılığı. Kurallar, bir senior'ın ilk bakışta aradığı şeylerdir; insan yorumunun yerini tutmaz ama ucuz hataları yakalar.

```python
# test: python 3.13 · numpy 2.5.4
# PC'de çalıştır — gerekli: numpy
# Kullanım: python denetim.py meta.json --csv-dir results/
# Benchmark meta verisini denetle: tekrar, örneklem, karıştırıcı, maliyet, CSV tutarlılığı.
import argparse, json
import numpy as np


def bul(severity, kod, mesaj, kanit=""):
    return {"severity": severity, "kod": kod, "mesaj": mesaj, "kanit": kanit}


def csv_stats(yol, cfg):
    import csv
    x, diger = [], set()
    with open(yol) as f:
        for r in csv.DictReader(f):
            if r.get("config") and r["config"] != cfg:
                diger.add(r["config"])
                continue
            if int(r["ok"]) == 1:
                x.append(float(r["ttft_ms"]))
    return (float(np.percentile(x, 95)) if x else None), sorted(diger)


def denetle(meta, csv_dir=""):
    f = []
    if not meta.get("revision"):
        f.append(bul("ORTA", "revizyon", "Model revizyonu yok; commit'e göre sonuç değişir."))
    if not meta.get("vllm"):
        f.append(bul("ORTA", "surum", "vLLM sürümü yazılmamış."))
    cfg = meta.get("configs", [])
    if len(cfg) < 3:
        f.append(bul("YUKSEK", "kapsam", "En az 3 yapılandırma gerekir.", f"{len(cfg)} var"))

    for c in cfg:
        ad = c.get("name", "?")
        if c.get("runs", 0) < 3:
            f.append(bul("YUKSEK", "tekrar", f"{ad}: tekrar < 3; varyans bilinmiyor."))
        if c.get("warmup_s", 0) <= 0:
            f.append(bul("ORTA", "isinma", f"{ad}: ısınma yok."))
        if c.get("n", 0) < 300:
            f.append(bul("ORTA", "orneklem", f"{ad}: n={c.get('n')} p95 için küçük."))
        if c.get("errors", 0) and not c.get("errors_included", True):
            f.append(bul("YUKSEK", "hata", f"{ad}: {c['errors']} hata ölçüm dışı."))
        if c.get("goodput") is None:
            f.append(bul("ORTA", "goodput", f"{ad}: SLO altında goodput yok."))
        if c.get("quantization", "bf16") != "bf16" and not c.get("quality_eval"):
            f.append(bul("YUKSEK", "kalite", f"{ad}: kuantizasyon var, kalite ölçümü yok."))
        if c.get("claim", {}).get("ttft_p95") and c.get("csv") and csv_dir:
            import os
            yol = os.path.join(csv_dir, c["csv"])
            if os.path.exists(yol):
                ger, diger = csv_stats(yol, ad)
                if diger:
                    f.append(bul("YUKSEK", "csv-karisik",
                                 f"{ad}: CSV'de başka config satırları var: {', '.join(diger)}."))
                iddia = c["claim"]["ttft_p95"]
                if ger and abs(ger - iddia) / iddia > 0.10:
                    f.append(bul("YUKSEK", "p95",
                                 f"{ad}: iddia {iddia:.0f} ms, CSV {ger:.0f} ms."))

    for i in range(len(cfg)):
        for j in range(i + 1, len(cfg)):
            a, b = cfg[i], cfg[j]
            fark = [k for k in ("max_num_seqs", "quantization", "prefix_cache", "request_rate")
                    if a.get(k) != b.get(k)]
            if len(fark) > 1:
                f.append(bul("YUKSEK", "karistirici",
                             f"{a.get('name')} vs {b.get('name')}: {len(fark)} değişken değişmiş.",
                             ", ".join(fark)))

    for c in cfg:
        cl = c.get("claim", {})
        if cl.get("cost_per_m") and cl.get("throughput") and meta.get("gpu_hourly"):
            hesap = meta["gpu_hourly"] / (cl["throughput"] * 3600 / 1e6)
            if abs(hesap - cl["cost_per_m"]) / max(hesap, 1e-9) > 0.15:
                f.append(bul("ORTA", "maliyet",
                             f"{c.get('name')}: iddia {cl['cost_per_m']} USD/1M, hesap {hesap:.2f} USD/1M."))
    return f


